// Keeps every part's A/B terrain tables in step with the store.
//
// Whenever terrainA/terrainB/seed/detail/userTerrain of a part changes (or the
// whole state loads) the part is refreshed after a short debounce: each slot's
// wanted table is described as a job (terrain-jobs.js), looked up in an LRU
// cache, otherwise generated by the generator (workers when possible). A
// finished table is posted to the DSP as a mip chain (copies are transferred,
// so the cached arrays stay valid) and announced with an engine 'terrain'
// event carrying the full-resolution level.
//
// Main-thread work per applied table is one copy of the chain (~1.4 MB for
// 512 x 512) plus the post; stats().maxApplyMs records the worst case.
//
// Slots are kept for all MAX_PARTS DSP parts and follow their tracks when the
// track list is reordered (the DSP moves its parts, and their tables, the same
// way), so a reorder regenerates nothing; only tracks in use are refreshed.

import { MAX_PARTS } from '../core/params.js';
import { partCount, trackIds, trackChange } from '../core/tracks.js';
import { jobFor, jobKey } from './terrain-jobs.js';

const SLOT_NAMES = ['A', 'B'];
const REGEN_KEYS = new Set(['terrainA', 'terrainB', 'seed', 'detail']);

function slotIndex(slot) {
  if (slot === 0 || slot === 'A' || slot === 'a') return 0;
  if (slot === 1 || slot === 'B' || slot === 'b') return 1;
  return -1;
}

const now = () => (typeof performance !== 'undefined' ? performance.now() : Date.now());

/**
 * @param {object} o
 * @param {object} o.store the app store
 * @param {(msg: object, transfer: ArrayBuffer[]) => void} o.post sends to the DSP
 * @param {(name: string, payload: object) => void} o.emit engine event emitter
 * @param {{size: number, free(): number, run(job): Promise<Array>}} o.generator
 * @param {number} [o.debounceMs]
 * @param {number} [o.cacheSize] maximum number of cached tables (LRU)
 */
export function createTerrainManager({ store, post, emit, generator, debounceMs = 60, cacheSize = 24 }) {
  const emptySlots = () => [0, 1].map(() => ({ want: null, have: null, failed: null, levels: null }));
  let slots = Array.from({ length: MAX_PARTS }, emptySlots);
  const cache = new Map();
  const queue = new Map();      // key -> job, waiting for a free generator
  const running = new Set();    // keys being generated
  let timers = new Array(MAX_PARTS).fill(0);
  let ids = trackIds(store.get('parts'));
  const live = () => partCount(store);
  let waiters = [];
  let disposed = false;
  const st = { generated: 0, cacheHits: 0, applied: 0, evicted: 0, errors: 0, maxApplyMs: 0, posted: 0 };

  function cacheGet(key) {
    const v = cache.get(key);
    if (v) { cache.delete(key); cache.set(key, v); }
    return v;
  }

  function cacheSet(key, levels) {
    cache.delete(key);
    cache.set(key, levels);
    while (cache.size > cacheSize) {
      cache.delete(cache.keys().next().value);
      st.evicted++;
    }
  }

  function wantedJob(part, s) {
    const slot = SLOT_NAMES[s];
    const params = store.get(`parts.${part}.params`);
    const ut = store.get(`parts.${part}.userTerrain.${slot}`);
    return jobFor(params, ut || null, slot, generator.size);
  }

  function isWanted(key) {
    for (let p = 0; p < live(); p++) for (const sl of slots[p]) if (sl.want === key && sl.have !== key) return true;
    return false;
  }

  function sendLevels(part, s, levels) {
    const copies = levels.map(l => ({ size: l.size, data: l.data.slice() }));
    post({ t: 'terrain', part, slot: s, levels: copies }, copies.map(c => c.data.buffer));
    st.posted++;
  }

  function apply(part, s, key, levels) {
    const t0 = now();
    sendLevels(part, s, levels);
    const sl = slots[part][s];
    sl.have = key;
    sl.failed = null;
    sl.levels = levels;
    st.applied++;
    st.maxApplyMs = Math.max(st.maxApplyMs, now() - t0);
    emit('terrain', { part, slot: SLOT_NAMES[s], size: levels[0].size, data: levels[0].data });
  }

  function refresh(part) {
    if (disposed) return;
    timers[part] = 0;
    if (part >= live()) return;
    for (let s = 0; s < 2; s++) {
      const job = wantedJob(part, s);
      const key = jobKey(job);
      const sl = slots[part][s];
      sl.want = key;
      if (sl.have === key) continue;
      const hit = cacheGet(key);
      if (hit) { st.cacheHits++; apply(part, s, key, hit); continue; }
      if (!running.has(key) && !queue.has(key)) queue.set(key, job);
    }
    pump();
    settle();
  }

  function pump() {
    while (!disposed && queue.size && generator.free() > 0) {
      const [key, job] = queue.entries().next().value;
      queue.delete(key);
      if (!isWanted(key)) continue;
      running.add(key);
      generator.run(job).then((levels) => {
        running.delete(key);
        if (disposed) return;
        st.generated++;
        cacheSet(key, levels);
        for (let p = 0; p < live(); p++) {
          for (let s = 0; s < 2; s++) {
            const sl = slots[p][s];
            if (sl.want === key && sl.have !== key) apply(p, s, key, levels);
          }
        }
      }, (err) => {
        running.delete(key);
        if (disposed) return;
        st.errors++;
        console.warn('[audio] terrain generation failed', err);
        for (const part of slots) for (const sl of part) if (sl.want === key) sl.failed = key;
      }).finally(() => { pump(); settle(); });
    }
  }

  function idle() {
    if (timers.some(Boolean) || queue.size || running.size) return false;
    for (let p = 0; p < live(); p++) for (const sl of slots[p]) if (sl.want !== sl.have && sl.want !== sl.failed) return false;
    return true;
  }

  function settle() {
    if (!waiters.length || !idle()) return;
    const w = waiters; waiters = [];
    for (const fn of w) fn();
  }

  function schedule(part) {
    if (disposed) return;
    clearTimeout(timers[part]);
    timers[part] = setTimeout(() => refresh(part), debounceMs);
  }

  function partsByPriority() {
    const n = live();
    const sel = Math.min(n - 1, Math.max(0, Math.round(store.get('ui.selectedPart') || 0)));
    const order = [];
    for (let i = 0; i < n; i++) order.push((sel + i) % n);
    return order;
  }

  /** The track list changed shape: slots move with their tracks, new tracks start empty. */
  function retrack(meta) {
    const r = trackChange(ids, store, meta);
    ids = r.ids;
    const change = r.change;
    if (!change) return;
    slots = change.perm.map(j => slots[j]);
    timers = change.perm.map(j => timers[j]);
    for (const i of change.fresh) { clearTimeout(timers[i]); timers[i] = 0; slots[i] = emptySlots(); }
    for (let i = change.count; i < MAX_PARTS; i++) { clearTimeout(timers[i]); timers[i] = 0; }
  }

  const offFree = typeof generator.onFree === 'function' ? generator.onFree(() => { pump(); settle(); }) : () => {};

  const off = store.subscribe('', (path, value, meta) => {
    if (path === '' || path === 'parts') { retrack(meta); for (const p of partsByPriority()) schedule(p); settle(); return; }
    const k = path.split('.');
    if (k[0] !== 'parts') return;
    const part = Number(k[1]);
    if (!(part >= 0 && part < live())) return;
    if (k.length === 2 || k[2] === 'userTerrain' || (k[2] === 'params' && (k.length === 3 || REGEN_KEYS.has(k[3])))) schedule(part);
  });

  // First fill: no debounce, selected part first.
  for (const p of partsByPriority()) refresh(p);

  return {
    /** Current full-resolution table of a slot ('A' | 'B' | 0 | 1), or null before it exists. */
    get(part, slot) {
      const s = slotIndex(slot);
      const p = Math.round(part);
      if (s < 0 || !(p >= 0 && p < MAX_PARTS)) return null;
      const lv = slots[p][s].levels;
      return lv ? { size: lv[0].size, data: lv[0].data } : null;
    },
    /** Resolves once every slot holds the table the store asks for. */
    whenIdle() {
      return new Promise((resolve) => { waiters.push(resolve); settle(); });
    },
    /**
     * Terrain messages for every table in place (not copied, not transferred):
     * for processorOptions.init of an offline render, which clones them.
     */
    messages() {
      const out = [];
      for (let p = 0; p < live(); p++) {
        for (let s = 0; s < 2; s++) {
          const lv = slots[p][s].levels;
          if (lv) out.push({ t: 'terrain', part: p, slot: s, levels: lv.map(l => ({ size: l.size, data: l.data })) });
        }
      }
      return out;
    },
    /** Re-post every current table (after the DSP node was rebuilt). */
    resendAll() {
      for (let p = 0; p < live(); p++) for (let s = 0; s < 2; s++) if (slots[p][s].levels) sendLevels(p, s, slots[p][s].levels);
    },
    /** Rebuild everything now (no debounce). */
    refreshAll() { for (const p of partsByPriority()) { clearTimeout(timers[p]); refresh(p); } },
    stats: () => ({ ...st, cached: cache.size, queued: queue.size, running: running.size }),
    dispose() {
      disposed = true;
      off();
      offFree();
      timers.forEach(t => clearTimeout(t));
      queue.clear();
      cache.clear();
      const w = waiters; waiters = [];
      for (const fn of w) fn();
    },
  };
}
